refentry.refsect1:
&reftitle.description;
stringfalseini_get stringoption
Restituisce il valore dell'opzione di configurazione in caso di successo.

&reftitle.parameters;




   option



     Il nome dell'opzione di configurazione.

  &reftitle.examples;



    Alcuni esempi di ini_get


<?php

/*
Il nostro php.ini contiene le seguenti impostazioni:

display_errors = On
opcache.enable_cli = Off
post_max_size = 8M
*/

echo 'display_errors = ' . ini_get('display_errors') . "\n";
echo 'opcache.enable_cli = ' . (int) ini_get('opcache.enable_cli') . "\n";
echo 'post_max_size = ' . ini_get('post_max_size') . "\n";
echo 'post_max_size + 1 = ' . (rtrim(ini_get('post_max_size'), 'KMG') + 1) . "\n";
echo 'post_max_size in byte = ' . ini_parse_quantity(ini_get('post_max_size'));

?>


    &example.outputs.similar;



display_errors = 1
opcache.enable_cli = 0
post_max_size = 8M
post_max_size+1 = 9
post_max_size in byte = 8388608
